import{_ as o,a0 as u,w as l,s as d,ao as i,I as p,x as s,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"Ubuntu 23.10 將引入安全增強的 PPA | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 23.10 將引入安全增強的 PPA | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 23.10 將引入安全增強的 PPA | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 23.10 將引入安全增強的 PPA | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230517.1 ⭐️ Ubuntu 23.10 To Bring Security Enhanced PPAs","title":"Ubuntu 23.10 將引入安全增強的 PPA","tag":"202305","desc":""},"relativePath":"202305/20230517.1 ⭐️ Ubuntu 23.10 To Bring Security Enhanced PPAs.md","filePath":"[post].md"}'),r={name:"202305/20230517.1 ⭐️ Ubuntu 23.10 To Bring Security Enhanced PPAs.md"};function g(P,t,b,c,h,m){const e=u("Link");return l(),d("div",null,[t[16]||(t[16]=i('<h1 id="ubuntu-23-10-將引入安全增強的-ppa" tabindex="-1">Ubuntu 23.10 將引入安全增強的 PPA <a class="header-anchor" href="#ubuntu-23-10-將引入安全增強的-ppa" aria-label="Permalink to “Ubuntu 23.10 將引入安全增強的 PPA”">​</a></h1><blockquote><p>Ubuntu 23.10 正在修改 PPA 的管理方式。</p></blockquote><p><img src="https://news.itsfoss.com/content/images/size/w1304/2023/05/ubuntu-better-ppa-management.png" alt="ubuntu 23.10 ppa"></p><p>Ubuntu 的升級不斷地增強功能並添加安全修復程序。但是，很少見到一些核心機制的更改。</p><p>在 Ubuntu 23.10 中，PPA 的功能得到了改進。至少，你在終端中看到警告會更少。</p><p>這是什麼意思呢？讓我詳細説明一下。</p><h3 id="gpg-密鑰問題" tabindex="-1">GPG 密鑰問題 <a class="header-anchor" href="#gpg-密鑰問題" aria-label="Permalink to “GPG 密鑰問題”">​</a></h3><p>傳統上，PPA 和其他外部存儲庫是通過 <code>/etc/apt/sources.list.d/</code> 中的 <code>.list</code> 來源列表文件進行管理的。此外，還有一個關聯的 GPG 密鑰環被放在 <code>/etc/apt/trusted.gpg.d</code> 中。</p><p>這被認為是一個潛在的安全問題，因為 GPG 密鑰是在系統級別上添加的。</p><p>怎麼回事？想像一下，你為存儲庫 A 添加密鑰以獲取包 AA，並從存儲庫 B 獲取包 BB。你的系統將很樂意接受用存儲庫 A 的密鑰簽名的 BB 包。因為它無法將密鑰與其各自的包關聯起來。</p><p>這是個問題，對吧？這種舊機制正在逐步淘汰。現在，GPG 密鑰信息將添加到外部存儲庫本身的 <code>sources.list</code> 中。這樣，GPG 密鑰將只接受其對應存儲庫的軟件包。</p><p>現有的 Ubuntu 用户可能已經遇到了使用 <code>/etc/apt/trusted.gpg.d</code> 中的舊方法添加 GPG 密鑰時出現的 <code>apt-key is deprecated</code> 警告。</p>',12)),p("p",null,[t[1]||(t[1]=s("以下是舊的 ",-1)),a(e,{href:"https://itsfoss.com/adding-external-repositories-ubuntu/?ref=news.itsfoss.com"},{default:n(()=>[...t[0]||(t[0]=[s("添加外部存儲庫",-1)])]),_:1}),t[2]||(t[2]=s(" 的方法的示例：",-1))]),t[17]||(t[17]=i(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install apt-transport-https curl</span></span>
<span class="line"><span>curl -sS https://dl.yarnpkg.com/debian/pubkey.gpg | sudo apt-key add -</span></span>
<span class="line"><span>sudo sh -c &#39;echo &quot;deb https://dl.yarnpkg.com/debian/ stable main&quot; &gt;&gt; /etc/apt/sources.list.d/yarn.list&#39;</span></span>
<span class="line"><span>sudo apt update &amp;&amp; sudo apt install yarn</span></span></code></pre></div><h3 id="ppa-將使用新的-gpg-密鑰機制" tabindex="-1">PPA 將使用新的 GPG 密鑰機制 <a class="header-anchor" href="#ppa-將使用新的-gpg-密鑰機制" aria-label="Permalink to “PPA 將使用新的 GPG 密鑰機制”">​</a></h3><p>現在，PPA 與添加外部存儲庫略有不同。在這裏，你不需要手動導入 GPG 密鑰並將其添加到 <code>/etc/apt/trusted.gpg.d</code> 目錄中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:dr-akulavich/lighttable</span></span>
<span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get install lighttable-installer</span></span></code></pre></div><p><strong>直到現在</strong>，所有事情都由 PPA 機制自己處理，與 PPA 相關聯的 GPG 密鑰會自動添加到 <code>/etc/apt/trusted.gpg.d</code> 目錄中。用户在這裏不需要做任何事情。</p><p>在 Ubuntu 23.10 中，引入了一種新的方法。</p><p>現在，PPA 將作為 deb822 格式的 <code>.sources</code> 文件添加，其中密鑰直接嵌入文件的 <code>Signed-By</code> 字段中。</p><p>使用這種方法，可以獲得以下一些優點：</p><ul><li>當刪除存儲庫時，相關的密鑰也會被刪除。</li><li>PPA 與其密鑰之間一一對應。沒有安全問題。</li></ul><p>在揭示這一消息的郵件列表中也提到：</p><blockquote><p>該密鑰專門用於特定的 PPA，無法用於其他存儲庫（與舊的存放所有存儲庫的源列表的 <code>trusted.gpg.d</code> 不同）。其他密鑰不能用於簽署該 PPA。</p></blockquote><p>總的來説，新的 PPA 版本將減少 “Key is stored in legacy trusted.gpg keyring” 和 “Manage keyring files in trusted.gpg.d instead” 警告。</p><p>我認為 Ubuntu 應該早些時候就引入這個改變，但遲到總比沒有好。 😊</p><p>你對 Ubuntu 處理 PPA 的這個新改變有什麼想法？請讓我知道你的想法。</p><hr>`,15)),p("p",null,[t[4]||(t[4]=s("via: ",-1)),a(e,{href:"https://news.itsfoss.com/ubuntu-23-10-set-to-let-you-easily-manage-ppas-while-enhancing-security/"},{default:n(()=>[...t[3]||(t[3]=[s("https://news.itsfoss.com/ubuntu-23-10-set-to-let-you-easily-manage-ppas-while-enhancing-security/",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=s("作者：",-1)),a(e,{href:"https://news.itsfoss.com/author/ankush/"},{default:n(()=>[...t[5]||(t[5]=[s("Ankush Das",-1)])]),_:1}),t[9]||(t[9]=s(" 選題：",-1)),a(e,{href:"https://github.com/lkxed/"},{default:n(()=>[...t[6]||(t[6]=[s("lkxed",-1)])]),_:1}),t[10]||(t[10]=s(" 譯者：ChatGPT 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[7]||(t[7]=[s("wxy",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=s("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[11]||(t[11]=[s("LCTT",-1)])]),_:1}),t[14]||(t[14]=s(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:n(()=>[...t[12]||(t[12]=[s("Linux中國",-1)])]),_:1}),t[15]||(t[15]=s(" 榮譽推出",-1))])])}const T=o(r,[["render",g]]);export{A as __pageData,T as default};
